"""Evaluate integer arithmetic expressions. See TASK.md.

Grammar (lowest to highest precedence):

    expr    := term (('+' | '-') term)*
    term    := unary (('*' | '//' | '%') unary)*
    unary   := ('-' | '+') unary | power
    power   := atom ('**' unary)?        # right-associative; exponent may be signed
    atom    := NUMBER | '(' expr ')'

The whole text is parsed into a tree first, so every syntax error is reported
as ValueError before any arithmetic runs.
"""

_OPERATORS = ("**", "//", "+", "-", "*", "%", "(", ")")


def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch in " \t":
            i += 1
        elif ch in "0123456789":
            start = i
            while i < n and text[i] in "0123456789":
                i += 1
            digits = text[start:i]
            if len(digits) > 1 and digits[0] == "0":
                raise ValueError("number with leading zero: %r" % digits)
            tokens.append(("num", int(digits)))
        elif ch == "/":
            if i + 1 < n and text[i + 1] == "/":
                tokens.append(("op", "//"))
                i += 2
            else:
                raise ValueError("unsupported operator '/'")
        elif ch == "*":
            if i + 1 < n and text[i + 1] == "*":
                tokens.append(("op", "**"))
                i += 2
            else:
                tokens.append(("op", "*"))
                i += 1
        elif ch in "+-%()":
            tokens.append(("op", ch))
            i += 1
        else:
            raise ValueError("unexpected character %r" % ch)
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def _peek_op(self, *ops):
        if self.pos < len(self.tokens):
            kind, val = self.tokens[self.pos]
            if kind == "op" and val in ops:
                return val
        return None

    def _advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse(self):
        if not self.tokens:
            raise ValueError("empty expression")
        tree = self._expr()
        if self.pos != len(self.tokens):
            raise ValueError("unexpected token at position %d" % self.pos)
        return tree

    def _expr(self):
        node = self._term()
        while True:
            op = self._peek_op("+", "-")
            if op is None:
                return node
            self._advance()
            node = (op, node, self._term())

    def _term(self):
        node = self._unary()
        while True:
            op = self._peek_op("*", "//", "%")
            if op is None:
                return node
            self._advance()
            node = (op, node, self._unary())

    def _unary(self):
        op = self._peek_op("+", "-")
        if op is not None:
            self._advance()
            return ("neg" if op == "-" else "pos", self._unary())
        return self._power()

    def _power(self):
        base = self._atom()
        if self._peek_op("**") is not None:
            self._advance()
            return ("**", base, self._unary())
        return base

    def _atom(self):
        if self.pos >= len(self.tokens):
            raise ValueError("missing operand")
        kind, val = self._advance()
        if kind == "num":
            return ("num", val)
        if val == "(":
            node = self._expr()
            if self._peek_op(")") is None:
                raise ValueError("unbalanced parentheses")
            self._advance()
            return node
        raise ValueError("unexpected operator %r" % val)


def _eval(node):
    tag = node[0]
    if tag == "num":
        return node[1]
    if tag == "neg":
        return -_eval(node[1])
    if tag == "pos":
        return +_eval(node[1])
    left = _eval(node[1])
    right = _eval(node[2])
    if tag == "+":
        return left + right
    if tag == "-":
        return left - right
    if tag == "*":
        return left * right
    if tag == "//":
        if right == 0:
            raise ZeroDivisionError("integer division by zero")
        return left // right
    if tag == "%":
        if right == 0:
            raise ZeroDivisionError("integer modulo by zero")
        return left % right
    if tag == "**":
        if right < 0:
            raise ValueError("negative exponent")
        return left ** right
    raise ValueError("unknown node %r" % (tag,))


def evaluate(text):
    """Value of an integer arithmetic expression. See TASK.md."""
    tree = _Parser(_tokenize(text)).parse()
    return _eval(tree)
